head.script:
/*
KR6003471G68
KR6003472G67
현재 tobe 에서 해당 채권번호로 조회 안됨
차후 퍼블에게 저 표준코드로 조회 후 나오는 화면 퍼블리싱 요청해야함
*/

scwin.param = "";

scwin.onpageload = function() {
    scwin.param = $c.data.getParameter();

    dma_search.set("stdCd", scwin.param.stdCd);

    $c.sbm.execute(sbm_search);
}

scwin.sbm_search_submitdone = function (e) {
    dma_srchMap.set("bndClssCd", dma_srchMap.get("bndClssNm") + "(" + dma_srchMap.get("bndClssCd") + ")" );

    var crwfndYn = dma_srchMap.get("crwfndYn");
    if(crwfndYn == "Y"){
        dma_srchMap.set("crwfndYn", "YES");
    } else if (crwfndYn == "N") {
        dma_srchMap.set("crwfndYn", "NO");
    }

    var coupnRtFinalYn = dma_srchMap.get("coupnRtFinalYn");
    if(coupnRtFinalYn == "Y"){
        dma_srchMap.set("coupnRtFinalYn", "확정");
    } else if (coupnRtFinalYn == "N") {
        dma_srchMap.set("coupnRtFinalYn", "미확정");
    }

    var infllnkYn = dma_srchMap.get("infllnkYn");
    if(infllnkYn == "Y"){
        dma_srchMap.set("infllnkYn", "YES");
    } else if (infllnkYn == "N") {
        dma_srchMap.set("infllnkYn", "NO");
    }

    var hbrdbndYn = dma_srchMap.get("hbrdbndYn");
    if(hbrdbndYn == "Y"){
        dma_srchMap.set("hbrdbndYn", "YES");
    } else if (hbrdbndYn == "N") {
        dma_srchMap.set("hbrdbndYn", "NO");
    }

    var sf = dma_crtvlList.get("sf");
    /*
    var crtvlSf2 = dma_crtvlList.get("crtvlSf2");
    var crtvlSf3 = dma_crtvlList.get("crtvlSf3");
    var crtvlSf4 = dma_crtvlList.get("crtvlSf4");
    */

    if(sf == "Y") {
        dma_crtvlList.set("cl", dma_crtvlList.get("cl")+ "(sf)");
    }
    /*
    if(crtvlSf2 == "Y") {
        dma_crtvlList.set("crtvlCl2", dma_crtvlList.get("crtvlCl2")+ "(sf)");
    }
    if(crtvlSf3 == "Y") {
        dma_crtvlList.set("crtvlCl3", dma_crtvlList.get("crtvlCl3")+ "(sf)");
    }
    if(crtvlSf4 == "Y") {
        dma_crtvlList.set("crtvlCl4", dma_crtvlList.get("crtvlCl4")+ "(sf)");
    }
    */

    if(dma_crtvlList.get("cd") == "9201") {
        dma_crtvlList.set("crtvlNm1", "NICE신용평가");
        spa_cd1.setValue(dma_crtvlList.get("cl"));
    } else if(dma_crtvlList.get("cd") == "9202") {
        dma_crtvlList.set("crtvlNm2", "한국신용평가");
        spa_cd2.setValue(dma_crtvlList.get("cl"));
    } else if(dma_crtvlList.get("cd") == "9203") {
        dma_crtvlList.set("crtvlNm3", "한국기업평가");
        spa_cd3.setValue(dma_crtvlList.get("cl"));
    } else if(dma_crtvlList.get("cd") == "9204") {
        dma_crtvlList.set("crtvlNm4", "서울신용정보");
        spa_cd4.setValue(dma_crtvlList.get("cl"));
    }

    var coupnRtDecsnBasIntCd = dma_srchMap.get("coupnRtDecsnBasIntCd");

    if(coupnRtDecsnBasIntCd == "01") {
        dma_srchMap.set("coupnRtDecsnBasIntNm", "최종호가 - 국고채권3개월");
    } else if(coupnRtDecsnBasIntCd == "02" ) {
        dma_srchMap.set("coupnRtDecsnBasIntNm", "최종호가 - 국고채권6개월");
    } else if(coupnRtDecsnBasIntCd == "03" ) {
        dma_srchMap.set("coupnRtDecsnBasIntNm", "최종호가 - 국고채권1년");
    } else if(coupnRtDecsnBasIntCd == "04" ) {
        dma_srchMap.set("coupnRtDecsnBasIntNm", "최종호가 - 국고채권3년");
    } else if(coupnRtDecsnBasIntCd == "05" ) {
        dma_srchMap.set("coupnRtDecsnBasIntNm", "최종호가 - 국고채권5년");
    } else if(coupnRtDecsnBasIntCd == "06" ) {
        dma_srchMap.set("coupnRtDecsnBasIntNm", "최종호가 - 국고채권10년");
    } else if(coupnRtDecsnBasIntCd == "07" ) {
        dma_srchMap.set("coupnRtDecsnBasIntNm", "최종호가 - 국고채권20년");
    } else if(coupnRtDecsnBasIntCd == "08" ) {
        dma_srchMap.set("coupnRtDecsnBasIntNm", "최종호가 - 국민주택1종(5년)");
    } else if(coupnRtDecsnBasIntCd == "10" ) {
        dma_srchMap.set("coupnRtDecsnBasIntNm", "최종호가 - CD91일물");
    } else if(coupnRtDecsnBasIntCd == "12" ) {
        dma_srchMap.set("coupnRtDecsnBasIntNm", "최종호가 - 국고채권30년");
    } else if(coupnRtDecsnBasIntCd == "20" ) {
        dma_srchMap.set("coupnRtDecsnBasIntNm", "최종호가 - 무보증회사채3년 AA-");
    } else if(coupnRtDecsnBasIntCd == "21" ) {
        dma_srchMap.set("coupnRtDecsnBasIntNm", "최종호가 - 무보증회사채3년 BBB-");
    } else if(coupnRtDecsnBasIntCd == "31" ) {
        dma_srchMap.set("coupnRtDecsnBasIntNm", "시가평가 - 시은보증");
    } else if(coupnRtDecsnBasIntCd == "32" ) {
        dma_srchMap.set("coupnRtDecsnBasIntNm", "시가평가 - 지방은보증");
    } else if(coupnRtDecsnBasIntCd == "33" ) {
        dma_srchMap.set("coupnRtDecsnBasIntNm", "시가평가 - 기타보증");
    } else if(coupnRtDecsnBasIntCd == "34" ) {
        dma_srchMap.set("coupnRtDecsnBasIntNm", "시가평가 - AAA");
    } else if(coupnRtDecsnBasIntCd == "35" ) {
        dma_srchMap.set("coupnRtDecsnBasIntNm", "시가평가 - AA+");
    } else if(coupnRtDecsnBasIntCd == "36" ) {
        dma_srchMap.set("coupnRtDecsnBasIntNm", "시가평가 - AA0");
    } else if(coupnRtDecsnBasIntCd == "37" ) {
        dma_srchMap.set("coupnRtDecsnBasIntNm", "시가평가 - AA-");
    } else if(coupnRtDecsnBasIntCd == "38" ) {
        dma_srchMap.set("coupnRtDecsnBasIntNm", "시가평가 - A+");
    } else if(coupnRtDecsnBasIntCd == "39" ) {
        dma_srchMap.set("coupnRtDecsnBasIntNm", "시가평가 - A0");
    } else if(coupnRtDecsnBasIntCd == "40" ) {
        dma_srchMap.set("coupnRtDecsnBasIntNm", "시가평가 - A-");
    } else if(coupnRtDecsnBasIntCd == "41" ) {
        dma_srchMap.set("coupnRtDecsnBasIntNm", "시가평가 - BBB+");
    } else if(coupnRtDecsnBasIntCd == "42" ) {
        dma_srchMap.set("coupnRtDecsnBasIntNm", "시가평가 - BBB0");
    } else if(coupnRtDecsnBasIntCd == "43" ) {
        dma_srchMap.set("coupnRtDecsnBasIntNm", "시가평가 - BBB-");
    } else if(coupnRtDecsnBasIntCd == "90" ) {
        dma_srchMap.set("coupnRtDecsnBasIntNm", "기타");
    }

};

scwin.btn_close_onclick = function (e) {
    $c.win.closePopup();
};
